'use strict';

// MODULES //

var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var isStringArray = require( '@stdlib/assert/is-string-array' ).primitives;
var isBoolean = require( '@stdlib/assert/is-boolean' ).isPrimitive;
var isPositiveInteger = require( '@stdlib/assert/is-positive-integer' ).isPrimitive;
var isObject = require( '@stdlib/assert/is-plain-object' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Validates function options.
*
* @private
* @param {Object} opts - destination for function options
* @param {Options} options - function options
* @param {StringArray} options.files - list of source file paths to test
* @param {string} [options.compiler] - C compiler to use
* @param {Array} [options.flags] - compiler flags
* @param {Array} [options.libraries] - libraries to link
* @param {Array} [options.include] - include directories
* @param {Array} [options.libpath] - library paths
* @param {Array} [options.sourceFiles] - additional source files
* @param {boolean} [options.verbose] - verbose output
* @param {PositiveInteger} [options.timeout] - maximum time in milliseconds
* @param {PositiveInteger} [options.maxBuffer] - maximum buffer size
* @returns {(Error|null)} error or null
*
* @example
* var opts = {};
* var options = {
*     'files': [ 'test.c' ]
* };
* var err = validate( opts, options );
* if ( err ) {
*     throw err;
* }
*/
function validate( opts, options ) {
	if ( !isObject( options ) ) {
		return new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}
	if ( hasOwnProp( options, 'files' ) ) {
		opts.files = options.files;
		if ( !isStringArray( opts.files ) ) {
			return new TypeError( format( 'invalid option. `%s` option must be an array of strings. Option: `%s`.', 'files', opts.files ) );
		}
	}
	if ( hasOwnProp( options, 'compiler' ) ) {
		opts.compiler = options.compiler;
		if ( !isString( opts.compiler ) ) {
			return new TypeError( format( 'invalid option. `%s` option must be a string. Option: `%s`.', 'compiler', opts.compiler ) );
		}
	}
	if ( hasOwnProp( options, 'flags' ) ) {
		opts.flags = options.flags;
		if ( !isStringArray( opts.flags ) ) {
			return new TypeError( format( 'invalid option. `%s` option must be an array of strings. Option: `%s`.', 'flags', opts.flags ) );
		}
	}
	if ( hasOwnProp( options, 'libraries' ) ) {
		opts.libraries = options.libraries;
		if ( !isStringArray( opts.libraries ) ) {
			return new TypeError( format( 'invalid option. `%s` option must be an array of strings. Option: `%s`.', 'libraries', opts.libraries ) );
		}
	}
	if ( hasOwnProp( options, 'include' ) ) {
		opts.include = options.include;
		if ( !isStringArray( opts.include ) ) {
			return new TypeError( format( 'invalid option. `%s` option must be an array of strings. Option: `%s`.', 'include', opts.include ) );
		}
	}
	if ( hasOwnProp( options, 'libpath' ) ) {
		opts.libpath = options.libpath;
		if ( !isStringArray( opts.libpath ) ) {
			return new TypeError( format( 'invalid option. `%s` option must be an array of strings. Option: `%s`.', 'libpath', opts.libpath ) );
		}
	}
	if ( hasOwnProp( options, 'sourceFiles' ) ) {
		opts.sourceFiles = options.sourceFiles;
		if ( !isStringArray( opts.sourceFiles ) ) {
			return new TypeError( format( 'invalid option. `%s` option must be an array of strings. Option: `%s`.', 'sourceFiles', opts.sourceFiles ) );
		}
	}
	if ( hasOwnProp( options, 'verbose' ) ) {
		opts.verbose = options.verbose;
		if ( !isBoolean( opts.verbose ) ) {
			return new TypeError( format( 'invalid option. `%s` option must be a boolean. Option: `%s`.', 'verbose', opts.verbose ) );
		}
	}
	if ( hasOwnProp( options, 'timeout' ) ) {
		opts.timeout = options.timeout;
		if ( !isPositiveInteger( opts.timeout ) ) {
			return new TypeError( format( 'invalid option. `%s` option must be a positive integer. Option: `%s`.', 'timeout', opts.timeout ) );
		}
	}
	if ( hasOwnProp( options, 'maxBuffer' ) ) {
		opts.maxBuffer = options.maxBuffer;
		if ( !isPositiveInteger( opts.maxBuffer ) ) {
			return new TypeError( format( 'invalid option. `%s` option must be a positive integer. Option: `%s`.', 'maxBuffer', opts.maxBuffer ) );
		}
	}
	return null;
}


// EXPORTS //

module.exports = validate;
